import subprocess
result = subprocess.run(['pdftotext', 'main.pdf', '-'], capture_output=True, text=True)
lines = result.stdout.split('\n')
page = 0
section_pages = []
for line in lines:
    if line.strip() == '' and len(line) == 0:
        continue
    if '\x0c' in line:
        page += 1
    # Look for section headers that indicate main body end
    if any(kw in line for kw in ['Limitations', 'Ethics Statement', 'References', 'Appendix']):
        section_pages.append((page, line.strip()[:80]))
    if any(kw in line for kw in ['Conclusion', 'Discussion']):
        section_pages.append((page, line.strip()[:80]))

print(f'Total pages in PDF: 32')
for p, s in section_pages[:15]:
    print(f'  Page {p}: {s}')
"

