import subprocess
result = subprocess.run(['pdftotext', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
# Split by form feed to get pages
pages = text.split('\x0c')
print(f'Total pages: {len(pages)}')
for i, page in enumerate(pages):
    for kw in ['Discussion', 'Conclusion', 'Limitations', 'Ethics Statement', 'References', 'Appendix A', 'Appendix B']:
        if kw in page and i < 20:
            # Find the line with the keyword
            for line in page.split('\n'):
                if kw in line:
                    print(f'  Page {i+1}: {line.strip()[:100]}')
                    break
